-- GENERATED by `wfi generate` from data/quest/quest-0092.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [92109] = { "Il mio primo set da alchimista", "Porta 5 Empty Vials, 5 Silverleaf e 5 Peacebloom alla giovane aspirante alchimista nel fienile di Moonbrook, a Westfall.", "Ehm... Salve, <signore/signorina>. Non dovrei parlare con gli sconosciuti, ma... Ehi, a cosa servono quelle bottigliette luccicanti che spuntano dal tuo zaino? Fai l'alchimista? Che forza!\n\nDa grande voglio fare l'alchimista anch'io. Papà non mi lascia giocare con le sue erbe; dice che è troppo pericoloso.\n\nBeh, io voglio cominciare a imparare adesso. Potresti procurarmi un po' di materiale, per favore, per favore?", nil, nil, 0xea2205a4, 0x2dcf0552, 0x3ea4b9d3, nil, nil, "...mm", nil, nil, 0x543226a7, nil, nil },
  [92110] = { "La mia prima vera pozione", "Raccogli 3 Murloc Eyes per la giovane aspirante alchimista nel fienile di Moonbrook, a Westfall.", "Wow, la mia primissima pozione! Sapevi che mescolando quelle due erbe la pozione all'inizio diventa di un rosso acceso?\n\nÈ stato divertente, ma mescolare qualche fiore non sembra il tipo di alchimia che fa papà. Lui usa anche altri ingredienti.\n\nNon so cos'altro usare, quindi proviamo la prima cosa che mi viene in mente! Vediamo... forse occhi di murloc? Che schifo, ma scommetto che succederà qualcosa.", nil, nil, 0x694e0f66, 0x5c5c86d7, 0xcdc27db4, nil, nil, "...mm" },
  [92124] = { "Inventario dei libri", "Parla con Daniel, l'assistente del Brother Paxton in biblioteca.", "Dobbiamo fare il punto su quanti libri mancano!\n\nVa' a parlare con quell'inutile del mio assistente, Daniel. Può fare un rapido inventario e farci sapere quanto è grave il problema.\n\nÈ ossessionato dalle varie professioni artigiane dell'Elwynn Forest. Quel ragazzo continua a pensare a quelle invece che al suo importante lavoro di aiutarmi.\n\nNon lasciare che si dilunghi sui mestieri, e scopri cosa è successo ai miei libri!", nil, "Sì, ho sentito. Ho avvertito il Brother Paxton tre volte dei kobold che scavavano gallerie sotto l'abbazia.\n\nSembra che i kobold abbiano preso un sacco di libri. Ci sono interi scaffali svuotati. Dovresti sentire cosa vuole che tu faccia il Brother Paxton.\n\nGià che sei qui, posso parlarti dei mestieri? Sarei felice di rispondere a qualsiasi domanda o di indicarti gli istruttori della zona.", 0x0231e44e, 0xe64d5a5a, 0x1c2a73d0, nil, 0x9453402b, "...m." },
  [92415] = { "Ricorda che ti amo", "Porta la Blood-Stained Letter all'Orphan Matron Nightingale, a Stormwind City.", "<Un fascio di pergamene strappato e macchiato è a malapena sopravvissuto al terreno calpestato dai non morti del cimitero. Parla di un bambino scomparso della famiglia Heartweaver. Forse la direttrice dell'orfanotrofio di Stormwind City ne saprà di più.>", "Cosa c'è, {name}? Cosa stai cercando?", "Heartweaver? Heartweaver...\n\nOh! Il piccolo Jeremy Heartweaver. È arrivato anni fa, dopo l'attacco a Lordaeron. Ha perso entrambi i genitori nell'attacco, poverino.\n\nIn realtà è stato adottato non molto tempo fa da una donna gentile di Duskwood.", 0x920a601f, 0xab38aea1, 0x10864cbe, 0x093eec87, 0x9c72863a, "....." },
  [92454] = { "Benvenuti!", "Porta il Thendal Grove Gift Voucher a Dalia Windbreeze.", "<Benvenuto/Benvenuta> in World of Warcraft!\n\nCome ringraziamento speciale per aver acquistato la World of Warcraft Collector's Edition, consegna questo buono regalo a Dalia Windbreeze, a Thendal Grove. Riceverai in cambio un dono: un piccolo compagno che ti accompagnerà nella tua ricerca di avventura e gloria.\n\nGrazie ancora, e buona permanenza in World of Warcraft!", nil, nil, 0xd6adcb4f, 0x498e8e33, 0x3ed9c7cd, nil, nil, "...mm" },
  [92456] = { "Un campione verde", "Raccogli un Fel Infused Blossom dalla City of Dalaran per Shylamiir, a Stormwind City.", "Se proprio devi disturbarmi, almeno renditi utile. Ho una commissione da sbrigare.\n\nPer essere una città di maghi, Dalaran ha un interesse sorprendente per la botanica. I Kirin Tor se ne stanno per conto loro, ma mi piacerebbe tanto avere un campione della loro vegetazione infusa di mana.\n\nSei chiaramente qualcuno a proprio agio dove non è gradito: forse potresti trovare un modo per entrare in città. Se ci riesci, riportami qualunque cosa cresca nel loro giardino centrale.", nil, nil, 0xb4915c29, 0xdc71b0cb, 0xb62ece69, nil, nil, "...mm" },
  [92479] = { nil, "Leggi la Scribbled Letter e parla con Tordrin Stemblade, alla Northshire Abbey.", "Mi è stato chiesto di sottoporti questo appena saresti <tornato/tornata> dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con il marchio di Tordrin Stemblade, il nostro istruttore dei cacciatori. Prenditi un momento per leggerla prima di occuparti di qualsiasi altra faccenda qui all'abbazia.", "Ah, hai ricevuto la mia lettera, {name}... bene.\n\nC'era un tempo in cui non avresti mai visto qualcuno della razza {race} con un arco in mano: ormai non più, a quanto pare. È un bene per Stormwind, ma un male per i kobold e le bestie mangiauomini della zona.", "Sistemati per bene, impara a conoscere il territorio e torna da me ogni volta che ti serve addestramento. Sarò qui giorno e notte.\n\nQuesta terra si fa sempre più pericolosa e, man mano che incontrerai altra gente, credo che scoprirai che tutti hanno problemi per cui farebbe comodo un aiuto, l'aiuto che sa dare chi è {class} con abilità. Buona fortuna.", nil, 0x0b04f03c, 0xaf9dc7c3, 0xb594010d, 0x84047297, "m...." },
  [92489] = { "Potere travolgente", "Uccidi il Mana Elemental nella City of Dalaran per l'High Sorcerer Andromath, a Stormwind City.", "I Kirin Tor sono da tempo alleati dell'Alliance. Con la distruzione della loro città per mano dell'arcidemone Archimonde, l'un tempo fiera città dei maghi è diventata solitaria e diffidente verso gli estranei.\n\nNegli ultimi anni hanno avviato lavori di ricostruzione per riportare la città di Dalaran al suo antico splendore. Tuttavia i rapporti indicano che faticano a contenere un'esplosione di energie arcane fuori controllo.\n\nDobbiamo aiutarli a disperdere questi attacchi, se non vogliamo perdere uno dei nostri alleati più potenti.", nil, nil, 0x311e78b1, 0xa949729f, 0x0b3dd36e, nil, nil, "...mm" },
  [92706] = { "RICERCATO: Bruuz", "Porta il Bruuz's Dorsal Fin a Gazlowe, a Ratchet.", "A tutti i pescatori!\n\nUno squalo gigante gira nelle acque vicino al molo di carico, attaccando marinai e piccole imbarcazioni. Gli scaricatori gli hanno dato il soprannome di \"Bruuz\". Una lauta ricompensa andrà a chi mi porterà la sua pinna!\n\n-- Gazlowe", "Cosa posso fare per te, {race}?", "Finalmente qualcuno ha ucciso quella bestia! Sai quanto è difficile mettere in acqua una squadra quando tutti in città gridano \"Squalo!\" in continuazione?\n\nForse metterò la pinna di quel mostro in una zuppa per cena stasera, giusto per ridere per ultimo.", 0x63f4d985, 0xf267f662, 0xc0d6b34c, 0x98361c3d, 0x66e7198a, "....." },
  [92744] = { "Branchie di murloc", "Alba Fairmoon vuole che tu raccolga 7 Longshore Murloc Gills lungo la costa di Westfall.", "La corruzione che colpisce i raccolti di Westfall potrebbe essere filtrata anche nell'oceano. Se anche i pesci locali sono colpiti, Stormwind potrebbe essere condannata alla carestia.\nRaccogli le branchie dei murloc lungo la costa e portamele. I murloc sono piuttosto resistenti, ma la loro fisiologia è estremamente sensibile alle sostanze contaminanti. Qualsiasi tossina nell'acqua di mare sarà subito evidente nelle branchie che troverai.", "Spero che i murloc non ti abbiano dato troppi problemi?", "Capisco... queste branchie sembrano sane, per ora. Ma non dobbiamo abbassare la guardia.", 0x18d085b1, 0x82b38f95, 0x84c4b3d3, 0xebb50726, 0x6a17bd1b, "....." },
  [92745] = { "Lo stato delle miniere", "Uccidi 4 Kobold Digger nella Jangolode Mine e 6 Riverpaw Miner nella Gold Coast Quarry.", "I campioni dei pozzi che hai raccolto contengono metalli tossici! Se non poniamo fine in fretta a questa corruzione, ci vorranno decenni prima che in questo terreno possano di nuovo crescere i raccolti.\nI Defias si sono impadroniti delle miniere di Westfall e usano creature come manodopera per spogliarle delle risorse. Ostacolali uccidendo i loro minatori nella Jangolode Mine a nord e nella Gold Coast Quarry a ovest.", nil, "Ben fatto, {name}. Ma temo che la fonte del veleno si trovi da qualche altra parte...", 0xdbfbda3d, 0xb4f30bb0, 0x0ed0182f, nil, 0x1b6794e0, "...m." },
  [92747] = { "Spionaggio a Moonbrook", "Raccogli 8 Suspicious Industrial Supplies a Moonbrook.", "Strano: il veleno non sembra provenire dalle miniere su cui hai indagato.\n\nMi dicono che le Deadmines sotto la città di Moonbrook siano le miniere più grandi e profonde di Westfall, ma sono abbandonate dalla First War. Possibile che le Deadmines siano di nuovo attive?\n\nTi prego, va' a Moonbrook, {name}, e cerca prove di attività minerarie o industriali. È l'ultima pista che abbiamo!", "Hai trovato qualcosa?", "Cos'è tutto questo?", 0xd607718d, 0x576e6434, 0xbc34590a, 0x2e14d88f, 0xb7fab352, "....." },
  [92748] = { "Consulenza esplosiva", "Recati nel Dwarven District di Stormwind e trova un ingegnere che possa aiutarti.", "Le provviste che hai trovato indicano un'enorme attività industriale da qualche parte nelle Deadmines. Non c'è dubbio che sia questa la fonte delle tossine che affliggono i terreni agricoli di Westfall. Dobbiamo fermarla, e in fretta.\n\nQualunque cosa ci sia laggiù sarà difficile da distruggere. Va' nel Dwarven District di Stormwind e trova un ingegnere che possa procurarci degli esplosivi.", nil, "Devi far saltare qualcosa?", 0x35aa9cd8, 0x37ec6835, 0x6c61d133, nil, 0x8969accc, "...m." },
  [92749] = { "Un piano a base di dinamite", "Procurati $N1 Rough Dynamite creandola, scambiandola o alla casa d'aste, poi torna da Sprite Jumpsprocket, nel Dwarven District di Stormwind.", "Sabotaggio industriale? Hai tutta la mia attenzione!\nCominceremo con un po' di dinamite...", "Fammi vedere quegli esplosivi, {name}!", "È un ottimo inizio! Ora mettiamo tutto insieme... e aggiungiamo un pizzico di grinta in più...", 0xdbe7a3f6, 0x63fc4165, 0x9f9816fe, 0x9f4c0c1a, 0xb7dd7511, "....." },
  [92750] = { "Detonazione a distanza", "Parla con qualcuno di Stormwind Intelligence per procurarti un detonatore a distanza.", "Immagino tu voglia un'esplosione \"controllata\"? Meno divertente, ma una buona scelta se vuoi tenerti tutti gli arti.\nTemo di non avere un detonatore a distanza: perché non vai a chiedere a quei furbetti di Stormwind Intelligence? Dovrebbero riuscire a trovarci qualcosa.", nil, "Mmm... Cerchi qualcosa di preciso, eh?", 0x9e430b80, 0x2e22edaa, 0xe691f760, nil, 0xe2f54704, "...m." },
  [92751] = { "Detonazione a distanza", "Porta il Remote Detonator Kit a Sprite Jumpsprocket, nel Dwarven District di Stormwind.", "Ti serve far saltare qualcosa? Ha a che fare con le tue attività a Moonbrook? Non fare quella faccia sorpresa. Lo SI:7 è informato di tutto ciò che accade nelle terre di Stormwind.\n\nSe hai intenzione di far esplodere qualcosa nelle grotte sotto Westfall, faresti bene a essere ben fuori prima. Prendi questo detonatore a distanza: è un prototipo recente dei nostri ingegneri.\n\nAh, e sarebbe meglio che non parlassi del mio coinvolgimento alla tua amica elfa.", nil, "Ottimo: è proprio il detonatore che ci serve!", 0x9e430b80, 0xecf85250, 0xc3fa1845, nil, 0x4868f6f1, "...m." },
  [92752] = { "Consulenza esplosiva", "Torna da Alba Fairmoon, a Westfall.", "Ecco fatto: la bomba è pronta! Attenzione con quel detonatore, adesso.", nil, "Sono felice che tu sia <tornato/tornata>, {name}.", 0x35aa9cd8, 0x767de34f, 0xeac04347, nil, 0x10bfbc2a, "...m." },
  [92753] = { "Distruzione nelle Deadmines", "Trova la forgia nascosta nelle Deadmines e piazza lì vicino gli Extra-Destructive Explosives. Poi raggiungi Alba Fairmoon all'uscita delle Deadmines.", "La fonte del veleno è probabilmente una grande forgia metallurgica di qualche tipo. Trova un modo per entrare nelle Deadmines e individua la forgia, poi piazza gli esplosivi.\nTi aspetterò sulle colline dietro Moonbrook. Al tuo ritorno potremo far detonare gli esplosivi. Speriamo che, eliminata la forgia, la terra possa cominciare a guarire.", nil, nil, 0x7e9a4fff, 0x13b8e5d8, 0xc733c35a, nil, nil, "...mm" },
  [92754] = { "Un nuovo bisogno di protezione dall'ombra", "Mantieni la tua reputazione con i Magram e porta $N1 Greater Shadow Protection Potions a Mirda, al Magram Village di Desolace.", "I nostri compagni di clan continuano ad avventurarsi più a sud, fino alla maledetta Valley of Bones e oltre.\n\nNonostante il tuo rango presso il nostro clan, non mi fido abbastanza di te da raccontarti i dettagli delle loro spedizioni. Comunque ti annoierebbero, <straniero/straniera>.\n\nCiò che ti interessa è il nostro bisogno di Greater Shadow Protection Potions, in grande quantità, per garantire la loro sopravvivenza. Portamene un po' e metterò una buona parola per te.", nil, nil, 0x687ae999, 0xb5521b2f, 0xa57a9cc9, nil, nil, "...mm" },
  [92755] = { "Misterioso misticismo", "Mantieni la tua reputazione con i Gelkis e porta $N1 Greater Mystic Essences a Halea, al Gelkis Village di Desolace.", "Ogni giorno che passa i nostri razziatori tornano con sempre meno armi ed equipaggiamenti di avventurieri caduti.\n\nAnche se non possiamo usare direttamente questi pezzi, li recuperiamo per ricavarne scarti. I più magici vengono a me, perché posso disincantarli e usare i misteriosi residui per incantare le nostre armi, in particolare quelle dei nostri windchaser.\n\nMi servono delle Greater Mystic Essences se devo fornire alla nostra prossima spedizione di razzia un equipaggiamento che valga qualcosa.", nil, nil, 0x7a268f3c, 0xe6a3f066, 0x69bc1d33, nil, nil, "...mm" },
  [92814] = { "Mi serve un sarto", "Mantieni la tua reputazione con i Gelkis e porta una White Bandit Mask a Molkar, al Gelkis Village di Desolace.", "La mia compagna, Halea, ha il compito di assicurarsi che le nostre armi siano potenziate con l'energia magica adatta.\n\nTutta l'idea dell'incantamento va ben oltre la mia comprensione, ma come centauro incaricato di tenere il nostro villaggio ben rifornito ed equipaggiato, so che Halea è spesso in ritardo con i suoi compiti, senza alcuna colpa.\n\nVorrei regalarle qualche abito semplice su cui esercitare la sua arte. Vedo alcuni avventurieri girare tra le tempeste di sabbia con semplici maschere sul viso. Potresti procurarmene qualcuna?", nil, nil, 0xd86e3465, 0x683448f5, 0x2e330903, nil, nil, "...mm" },
  [92817] = { "Tecnica del cuoio", "Mantieni la tua reputazione con i Gelkis e porta un Barbaric Harness a Talra, al Gelkis Village di Desolace.", "Convincere i miei compagni di clan Gelkis a indossare un'armatura è quasi impossibile, nonostante le numerose perdite subite per lame o dardi nel petto.\n\nHo il compito di progettare un gilet che offra una protezione ragionevole, senza il presunto \"prurito\" di cui si lamentano. Le provviste scarseggiano, quindi non oso sprecare cuoio prezioso in robaccia.\n\n<Straniero/Straniera>, mi porteresti un'imbracatura adatta a un centauro rozzo? Vorrei imparare dalla tua tecnica.", nil, nil, 0xe1654f2c, 0x78d11657, 0xe5dbca65, nil, nil, "...mm" },
  [92818] = { "Grosse, anzi, enormi asce di ferro", "Mantieni la tua reputazione con i Magram e porta $N1 Massive Iron Axes a Grolkar, al Magram Village di Desolace.", "Ci servono più armi!\n\nPiù. Armi!\n\nIn che altro modo i Magram schiacceranno quei Gelkis mingherlini?\n\nVoglio vedere cosa sai fare, <straniero/straniera>. Portami asce. Grosse, anzi, enormi!\n\nMuoviti!", nil, nil, 0x1c3f85ce, 0x4f5d09f2, 0xdfe891b2, nil, nil, "...mm" },
  [92819] = { "Distruzione nelle Deadmines", nil, nil, nil, nil, 0x7e9a4fff, nil, nil, nil, nil, ".mmmm" },
  [92844] = { "Una montagna di ossa", "Mantieni la tua reputazione con i Magram e porta $N1 Gently Cursed Bones a Orgrul, a sud del Magram Village di Desolace.", "Una qualche energia negromantica ha permeato tutta la Valley of Bones, per motivi che non abbiamo ancora capito.\n\nAnche quei motivi per noi non hanno importanza. Ora la magia è nostra, e chi non combatte con lama o mazza viene addestrato in questa nuova magia.\n\nSe pensi che voglia cominciare con un compito impegnativo, ripensaci. Per ora va' nella Valley of Bones e procurami qualche osso. Sono sicuro che sai cavartela.", nil, nil, 0x87f6217c, 0x119ae063, 0xf8d93bb4, nil, nil, "...mm" },
  [92909] = { "Smontare le mietitrici", "Ozwin Ironsprocket, alla Saldean's Farm, vuole che tu gli porti 14 Golem Isosprings e 5 Harvester Gyrostabilizers.", "Oh no... ora sono nei guai!\n\nHo sentito delle mietitrici che terrorizzano i campi di Westfall, così sono venuto fin da Ironforge per vedere se potevo ricalibrarle. Ma sono molto più aggressive di quanto prevedessero i miei calcoli, e mi hanno inseguito fino a questa stalla!\n\nSe avessi un po' di isospring e gyrostabilizer delle mietitrici, potrei costruire un congegno per coprirmi la fuga. Potresti raccogliere i pezzi per me?", "Là fuori è un disastro, {name}! Hai raccolto i pezzi che mi servono?", "Grazie mille! Mi metto al lavoro su un piano di fuga. Nel frattempo, prendi questo!", 0xced8714e, 0xb9cd3180, 0x7c112345, 0x86f9d0d9, 0x2ee3cde7, "....." },
  [92910] = { "Smontare le mietitrici", nil, nil, nil, nil, 0xced8714e, nil, nil, nil, nil, ".mmmm" },
  [92911] = { "Smontare le mietitrici", nil, nil, nil, nil, 0xced8714e, nil, nil, nil, nil, ".mmmm" },
})
